mapper.select:
SELECT r.id, r.course_id AS courseId, c.title AS courseTitle, r.user_id AS userId, u.username AS username, u.nickname AS nickname, r.rating, r.content, r.like_count AS likeCount, r.create_time AS createTime FROM tb_course_review r LEFT JOIN tb_course c ON r.course_id = c.id LEFT JOIN tb_user u ON r.user_id = u.id WHERE r.status = 1
AND r.course_id = #{courseId}
AND r.rating = #{rating}
AND ( u.username LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') OR c.title LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY r.create_time DESC
